import{_ as t,o as u,c as q,a2 as l}from"./chunks/framework.BbQrW5_t.js";const g=JSON.parse('{"title":"《天道解读》读书笔记","description":"","frontmatter":{"title":"《天道解读》读书笔记","date":"2026-07-28T00:00:00.000Z","tags":["读书笔记","天道","文化属性","阳明心学","商业思维"]},"headers":[],"relativePath":"study/reading-notes/20260728-《天道解读》读书笔记.md","filePath":"study/reading-notes/20260728-《天道解读》读书笔记.md","lastUpdated":1785220701000}'),a={name:"study/reading-notes/20260728-《天道解读》读书笔记.md"};function r(i,o,p,e,n,s){return u(),q("div",null,[...o[0]||(o[0]=[l('<h1 id="《天道解读》读书笔记" tabindex="-1">《天道解读》读书笔记 <a class="header-anchor" href="#《天道解读》读书笔记" aria-label="Permalink to &quot;《天道解读》读书笔记&quot;">​</a></h1><blockquote><p>作者：佚名 | 阅读时间：2026-07-28</p></blockquote><hr><h2 id="📌-一、核心观点与逻辑骨架" tabindex="-1">📌 一、核心观点与逻辑骨架 <a class="header-anchor" href="#📌-一、核心观点与逻辑骨架" aria-label="Permalink to &quot;📌 一、核心观点与逻辑骨架&quot;">​</a></h2><h3 id="一句话概括" tabindex="-1">一句话概括 <a class="header-anchor" href="#一句话概括" aria-label="Permalink to &quot;一句话概括&quot;">​</a></h3><p>本书是对《遥远的救世主》（电视剧《天道》原著）的深度解读，核心围绕&quot;文化属性&quot;展开——强势文化vs弱势文化的根本差异在于思维模式：强势文化遵循&quot;实事求是&quot;，弱势文化依赖&quot;等靠要&quot;。书中通过丁元英、芮小丹、肖亚文等人物案例，揭示改命的核心密码：心即理（认识自己的理）、致良知（觉察第一念）、知行合一（意识与潜意识统一）。阳明心学三要素是破局改命的根本心法，&quot;圣人之道，吾性自足&quot;——你本具足，只是被&quot;理&quot;束缚而不自知。</p><h3 id="核心论点" tabindex="-1">核心论点 <a class="header-anchor" href="#核心论点" aria-label="Permalink to &quot;核心论点&quot;">​</a></h3><p>按文本理解罗列核心论点，不限制条数：</p><ol><li><p><strong>文化属性决定命运</strong>：强势文化直接获取，弱势文化等靠要。思维模式的差异是贫富分化的根源，弱势文化总在幻想&quot;遇见贵人&quot;，强势文化在积累条件、创造机会。</p></li><li><p><strong>分寸感是获取机会的核心能力</strong>：肖亚文不问&quot;为什么&quot;，先思考；欧阳雪知道自己几斤几两，不越雷池一步。分寸感的本质是对因果的敬畏。</p></li><li><p><strong>合理化思维是穷人的思维陷阱</strong>：刘冰买唱片压价到50元，还要给自己找&quot;我是恩人&quot;的心理建设。穷人总在用最小代价博取最大利益，不知道人情要还。</p></li><li><p><strong>长期价值思维消除焦虑</strong>：把目标定在&quot;每天写1000字&quot;而非&quot;成为作家&quot;，每一天都走在成功的路上。短期思维模式无法经历完整的事物发展周期。</p></li><li><p><strong>利益不等于金钱</strong>：刘冰的利益是钱和宝马，林雨峰的利益是面子，冯世杰的利益是王庙村的未来，芮小丹的利益是觉悟。选择的利益不同，结局也不同。</p></li><li><p><strong>作为价值vs人生价值</strong>：作为价值是社会赋予你的价值（职业、收入、地位），人生价值是你这辈子要成为什么样的人。芮小丹当警察是人生价值，不是职业选择。</p></li><li><p><strong>神学宗教的社会功能</strong>：神学、儒家文化的本质是让社会有序进行。窄门不是天堂入口，而是自我救赎的起点——你不知道你，所以你是你。</p></li><li><p><strong>游戏的五个层面</strong>：创造游戏的人（道法自然）、制定规则的人（丁元英）、控制资源的人（肖亚文）、精通规则的人、被游戏玩的人（叶冯刘）。认清自己在哪一层。</p></li><li><p><strong>商业的本质是提供价值</strong>：发心决定结果。如果你的目标是&quot;我要成为作家&quot;，潜意识认定自己还没成功；如果目标是&quot;每天写1000字&quot;，每完成一次都是成功。</p></li><li><p><strong>心即理：你的心被&quot;理&quot;束缚</strong>：父母、老师、专家给你的&quot;理&quot;（10点必须睡觉、必须考上好大学）不是你的理。心被物欲蒙蔽，活的不像自己。</p></li><li><p><strong>致良知：觉察第一念</strong>：良知发动的那一刻，是你当下最感兴趣的念头，最容易投入精力的念头。不要预设结果，允许可能与事实之间存在演化的过程。</p></li><li><p><strong>知行合一：意识与潜意识统一</strong>：知道就一定会行动，如果没有行动，就一定不知道。知行合一是一种状态，是觉悟的状态，是心流的状态。</p></li></ol><h3 id="逻辑模型" tabindex="-1">逻辑模型 <a class="header-anchor" href="#逻辑模型" aria-label="Permalink to &quot;逻辑模型&quot;">​</a></h3><p>文化属性决定思维模式 → 思维模式决定行为选择 → 行为积累形成命运 → 改命必须从心开始（心即理→致良知→知行合一）</p><p>强势文化：实事求是 → 积累条件 → 创造机会 → 掌控命运 弱势文化：等靠要 → 合理化幻想 → 短期行为 → 被动轮回</p><h3 id="启发思考的5个点" tabindex="-1">启发思考的5个点 <a class="header-anchor" href="#启发思考的5个点" aria-label="Permalink to &quot;启发思考的5个点&quot;">​</a></h3><ol><li><p><strong>你身边有&quot;刘冰&quot;吗？</strong> 短期思维模式的人，做事有始无终，完美错过所有风口。反思：自己的哪个项目是&quot;有始无终&quot;的？为什么放弃？是被&quot;理&quot;束缚了，还是从未&quot;致良知&quot;？</p></li><li><p><strong>分寸感从何而来？</strong> 肖亚文找芮小丹&quot;照应&quot;丁元英，不是因为她漂亮，而是因为她&quot;办事有分寸&quot;。反思：在贵人面前，你有没有问&quot;为什么&quot;，还是先思考？你是用一顿饭还人情，还是用价值交换？</p></li><li><p><strong>利益定义差异如何影响人生？</strong> 刘冰的利益是钱，林雨峰的利益是面子，芮小丹的利益是觉悟。反思：你眼中的利益是什么？金钱、地位、还是内心的平静？你的利益选择决定了你的结局。</p></li><li><p><strong>&quot;合理化&quot;有哪些伪装？</strong> &quot;我只是想帮忙&quot;、&quot;这不地道但我是恩人&quot;、&quot;反正也没人知道&quot;。反思：你有没有在给自己找借口？当你开始合理化一个行为时，警惕：这可能是弱势文化的思维陷阱。</p></li><li><p><strong>知行合一为什么这么难？</strong> 王阳明说：知而不行，只是未知。反思：你&quot;知道&quot;却没行动的事情有哪些？早睡早起、锻炼身体、读书学习。是意识到了，但潜意识还没到位。如何&quot;致良知&quot;？刻意练习，每天1000字。</p></li></ol><hr><h2 id="💡-二、认知升维与碰撞" tabindex="-1">💡 二、认知升维与碰撞 <a class="header-anchor" href="#💡-二、认知升维与碰撞" aria-label="Permalink to &quot;💡 二、认知升维与碰撞&quot;">​</a></h2><h3 id="反直觉洞察" tabindex="-1">反直觉洞察 <a class="header-anchor" href="#反直觉洞察" aria-label="Permalink to &quot;反直觉洞察&quot;">​</a></h3><p><strong>1. 神话的本质是平常事</strong></p><p>丁元英说：&quot;这世上原本就没有什么神话，所谓的神话不过是常人的思维所不理解的平常事。&quot;高手的&quot;神操作&quot;，在常人眼里是神话，在高人眼里只是实事求是。</p><p>对技术管理者的冲击：我们总在寻找&quot;银弹&quot;、&quot;最佳实践&quot;，却忽略了最朴素的道理——积累条件、实事求是。丁元英格律诗案的核心不是神机妙算，而是调研王庙村、了解老人家的智慧、尊重因果。</p><p><strong>2. 尊老的本质是尊重智慧</strong></p><p>丁元英等刘大爷吃饭，不是因为个人素养，而是因为老人最了解王庙村发展历程。刘邦年长项羽20多岁，见过的人情世故、知道什么人该忍、什么人该打压——这是岁月沉淀的智慧。</p><p>对技术管理者的冲击：我们崇尚&quot;能力主义&quot;，却忽略了&quot;家有一老如有一宝&quot;。在团队管理中，资深员工的价值不是产出代码量，而是经历过的坑、见过的人、积累的智慧。</p><p><strong>3. 长期价值思维消除焦虑</strong></p><p>作者把自己的模式调整为：我要是5年之内能把这件事做成了，我就很成功。所以，每一天都走在成功的路上，而不是花精力去琢磨什么时候能赚钱。</p><p>对技术管理者的冲击：焦虑的本质是目标错了。如果你的目标是&quot;成为架构师&quot;，潜意识会告诉你&quot;你还没成功&quot;；如果目标是&quot;每天写100行代码、每周读一篇论文&quot;，每完成一次都是成功。</p><h3 id="系统映射" tabindex="-1">系统映射 <a class="header-anchor" href="#系统映射" aria-label="Permalink to &quot;系统映射&quot;">​</a></h3><h4 id="映射到技术团队管理" tabindex="-1">映射到技术团队管理 <a class="header-anchor" href="#映射到技术团队管理" aria-label="Permalink to &quot;映射到技术团队管理&quot;">​</a></h4><p><strong>分寸感与责任边界</strong></p><p>书中丁元英指定欧阳雪做出资人，因为她&quot;办事有分寸&quot;——不会先问&quot;为什么&quot;，会先思考；知道自己几斤几两，不越雷池一步。</p><p>映射到技术团队管理：</p><ul><li><strong>代码评审的分寸</strong>：不是每个问题都要指指点点，知道哪些是原则问题、哪些是风格偏好</li><li><strong>跨部门协作的分寸</strong>：知道什么该管、什么不该管，不越俎代庖</li><li><strong>向上汇报的分寸</strong>：问题自己先思考，不要做&quot;伸手党&quot;</li></ul><p>涟漪效应：团队成员如果缺乏分寸感，会消耗领导大量时间&quot;解释为什么&quot;，最终失去信任，错失机会。</p><p><strong>长期价值vs短期KPI</strong></p><p>刘冰的失败不是贪心，而是&quot;做事没长性&quot;——服务员赚钱就去干服务员，唱片赚钱就开店，要打官司马上翻脸。</p><p>映射到技术团队管理：</p><ul><li><strong>技术选型</strong>：是选&quot;好招人&quot;的技术栈，还是选&quot;团队能成长&quot;的技术栈？</li><li><strong>项目排期</strong>：是追求短期上线，还是积累可复用的组件库？</li><li><strong>团队培养</strong>：是压榨现有能力，还是投资学习成长？</li></ul><p>涟漪效应：短期思维团队，永远在&quot;救火&quot;循环中，无法积累核心竞争力。</p><h4 id="映射到家庭教育" tabindex="-1">映射到家庭教育 <a class="header-anchor" href="#映射到家庭教育" aria-label="Permalink to &quot;映射到家庭教育&quot;">​</a></h4><p><strong>作为价值vs人生价值</strong></p><p>芮小丹当警察，丁元英认为她应该辞职从事影视行业发挥更大价值（作为价值），但芮小丹坚持自己的选择（人生价值）——她要的是&quot;锄强扶弱&quot;的精神价值。</p><p>映射到家庭教育：</p><ul><li><strong>学业选择</strong>：是追求&quot;好就业、高薪&quot;的专业（作为价值），还是孩子真正感兴趣的领域？</li><li><strong>课外活动</strong>：是报&quot;有用&quot;的班，还是让孩子探索&quot;有意思&quot;的事？</li><li><strong>职业规划</strong>：是告诉孩子&quot;你要成为什么&quot;，还是让孩子发现&quot;我想成为什么&quot;？</li></ul><p>涟漪效应：用作为价值定义孩子的人生，会培养出&quot;空心人&quot;——外在成功、内在空虚。芮小丹可贵之处：她知道自己要什么，不为社会定义的价值所动摇。</p><p><strong>致良知与第一念</strong></p><p>芮小丹对丁元英心动那一刻，决定要靠近他，不问过去，不想将来——这就是良知发动的第一念。而肖亚文预设了结果（爱上这个男人就等于迈进了地狱），错过了火花。</p><p>映射到家庭教育：</p><ul><li><strong>孩子畏难时</strong>：是预设&quot;他做不到&quot;，还是允许他与困难&quot;演化&quot;？</li><li><strong>孩子想学什么</strong>：是立刻分析&quot;有没有用&quot;，还是支持他先试试？</li><li><strong>孩子犯错时</strong>：是马上批评&quot;早就说了&quot;，还是陪他复盘因果？</li></ul><p>涟漪效应：家长过度预设结果，会阻断孩子的&quot;致良知&quot;——孩子不敢尝试，因为已经被告知&quot;不行&quot;。</p><hr><h2 id="🎯-三、专属建议生成-双轨并行" tabindex="-1">🎯 三、专属建议生成（双轨并行） <a class="header-anchor" href="#🎯-三、专属建议生成-双轨并行" aria-label="Permalink to &quot;🎯 三、专属建议生成（双轨并行）&quot;">​</a></h2><h3 id="路线a-技术管理线-3条建议" tabindex="-1">路线A：技术管理线（3条建议） <a class="header-anchor" href="#路线a-技术管理线-3条建议" aria-label="Permalink to &quot;路线A：技术管理线（3条建议）&quot;">​</a></h3><p><strong>建议一：建立&quot;分寸感&quot;检查清单 🔴🔴🔴</strong></p><p>每周复盘：这周我有没有做&quot;伸手党&quot;？有没有问&quot;为什么&quot;之前先思考？有没有越权决策？</p><p>具体动作：</p><ul><li>建立&quot;提问前思考三分钟&quot;原则</li><li>代码评审只抓原则问题，风格问题放开</li><li>向上汇报带方案，不带问题</li></ul><p>为什么重要：分寸感是获取机会的入场券。丁元英把格律诗交给欧阳雪，因为她&quot;办事有分寸&quot;；肖亚文成掌门人，因为她&quot;先思考再问&quot;。</p><p><strong>建议二：长期价值锚定技术债务 🔴🔴</strong></p><p>把技术债务治理纳入5年规划，而非季度OKR。每消除一个债务，距离&quot;技术自由的团队&quot;就近一步。</p><p>具体动作：</p><ul><li>建立技术债务台账，而非散落在JIRA</li><li>每个版本留10%容量还债，不追求立刻见效</li><li>团队成员轮值&quot;还债周&quot;，积累全局视野</li></ul><p>为什么重要：刘冰的教训——短期思维无法经历完整周期。技术债务如果不长期治理，团队会陷入&quot;救火轮回&quot;。</p><p><strong>建议三：尊重&quot;老人家&quot;的智慧 🔴</strong></p><p>团队里的资深员工，价值不是代码产出，而是见过的坑、踩过的雷。</p><p>具体动作：</p><ul><li>重要决策前，单独请教资深员工&quot;您怎么看&quot;</li><li>团队分享会，请资深员工讲&quot;我踩过的坑&quot;</li><li>代码评审时，观察资深员工关注的点</li></ul><p>为什么重要：丁元英等刘大爷吃饭，不是因为礼貌，而是因为老人最了解王庙村发展历程。刘邦年长项羽20多岁，见过的世面决定了楚汉之争的结局。</p><h3 id="路线b-父亲育儿线-3条建议" tabindex="-1">路线B：父亲育儿线（3条建议） <a class="header-anchor" href="#路线b-父亲育儿线-3条建议" aria-label="Permalink to &quot;路线B：父亲育儿线（3条建议）&quot;">​</a></h3><p><strong>建议一：允许孩子&quot;演化&quot;，不预设结果 🔴🔴🔴</strong></p><p>孩子畏难、想放弃时，不要说&quot;你看我就说不行吧&quot;，而是说&quot;我们先试试，不行再调整&quot;。</p><p>具体动作：</p><ul><li>孩子说&quot;我不会&quot;，回：&quot;我们先做第一步，看看会发生什么&quot;</li><li>孩子想学什么，先让试一周，再讨论要不要继续</li><li>孩子犯错时，先问&quot;你学到了什么&quot;，再讨论后果</li></ul><p>为什么重要：芮小丹的智慧——允许可能与事实之间存在一个演化的过程。致良知的第一念，是不预设结果。</p><p><strong>建议二：区分&quot;作为价值&quot;和&quot;人生价值&quot; 🔴🔴</strong></p><p>和孩子聊职业时，问两个问题：一是&quot;社会需要什么&quot;（作为价值），二是&quot;你想成为什么样的人&quot;（人生价值）。</p><p>具体动作：</p><ul><li>不说&quot;你要考上好大学&quot;，而说&quot;你想成为什么样的人？上大学是其中一条路&quot;</li><li>不说&quot;这个专业好就业&quot;，而说&quot;你感兴趣的事，做一辈子也不累&quot;</li><li>不说&quot;你要听话&quot;，而说&quot;你的选择，你承担后果&quot;</li></ul><p>为什么重要：芮小丹的坚持——当警察是她的人生价值，不是职业选择。丁元英的无力——他一直活在外界价值中被社会定义。</p><p><strong>建议三：建立家庭&quot;知行合一&quot;打卡 🔴</strong></p><p>每周和孩子一起做一件事（不是监督，是一起做），持续100天。完成一件事，比说教100遍更有力量。</p><p>具体动作：</p><ul><li>选一件孩子想做的事（不是你想让他做的事）</li><li>每天/每周固定时间做，不强求完美</li><li>记录过程，100天后复盘&quot;我们学到了什么&quot;</li></ul><p>为什么重要：王阳明剿匪百战百胜，因为知行合一。作者写12万字《天道解读》，不是每天有灵感，是每天逼自己写。知而不行，只是未知。</p><hr><h2 id="📋-四、行动计划-三级火箭" tabindex="-1">📋 四、行动计划（三级火箭） <a class="header-anchor" href="#📋-四、行动计划-三级火箭" aria-label="Permalink to &quot;📋 四、行动计划（三级火箭）&quot;">​</a></h2><h3 id="短期实验-1-2周" tabindex="-1">短期实验（1-2周） <a class="header-anchor" href="#短期实验-1-2周" aria-label="Permalink to &quot;短期实验（1-2周）&quot;">​</a></h3><ul><li>[ ] 建立&quot;分寸感&quot;检查清单，贴在显示器边，每天下班前看一眼</li><li>[ ] 本周团队会议，请教一位资深员工&quot;您怎么看&quot;</li><li>[ ] 和孩子聊一次&quot;你想成为什么样的人&quot;，记录在备忘录</li></ul><h3 id="中期植入-1-3个月" tabindex="-1">中期植入（1-3个月） <a class="header-anchor" href="#中期植入-1-3个月" aria-label="Permalink to &quot;中期植入（1-3个月）&quot;">​</a></h3><ul><li>[ ] 技术债务台账建立，每个版本预留10%容量还债</li><li>[ ] 团队分享会引入&quot;踩坑故事&quot;环节，资深员工主讲</li><li>[ ] 家庭建立&quot;知行合一&quot;打卡，每周和孩子一起做一件事，持续12周</li></ul><h3 id="长期重塑-1年以上" tabindex="-1">长期重塑（1年以上） <a class="header-anchor" href="#长期重塑-1年以上" aria-label="Permalink to &quot;长期重塑（1年以上）&quot;">​</a></h3><ul><li>[ ] 团队培养出&quot;分寸感&quot;文化，新成员入职有分寸感培训</li><li>[ ] 孩子形成&quot;致良知&quot;习惯，面对选择时先问&quot;我的第一念是什么&quot;</li><li>[ ] 自己实现&quot;知行合一&quot;状态，想做的事自动转化为行动</li></ul><hr><h2 id="🔗-五、跨界联想与质疑" tabindex="-1">🔗 五、跨界联想与质疑 <a class="header-anchor" href="#🔗-五、跨界联想与质疑" aria-label="Permalink to &quot;🔗 五、跨界联想与质疑&quot;">​</a></h2><h3 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h3><p><strong>《王阳明大传》——知行合一的源头</strong></p><p>《天道解读》下册花大量篇幅讲阳明心学（心即理、致良知、知行合一），与《王阳明大传》形成互补。前者用小说案例解读心学应用，后者讲王阳明生平和思想脉络。</p><p>冲突点：《王阳明大传》强调&quot;格物致知&quot;的学术路径，《天道解读》强调&quot;致良知是觉察第一念&quot;的实用路径。两种解读，一种本质——不被&quot;理&quot;束缚，回归本心。</p><p><strong>《遥远的救世主》——小说原著</strong></p><p>《天道解读》是对《遥远的救世主》的批注。建议先看原著，再看解读。原著讲故事，解读拆逻辑。</p><p>互补点：原著提供人物案例（丁元英、芮小丹、肖亚文），解读提供思维模型（文化属性、分寸感、长期价值）。两者结合，才能从&quot;看懂故事&quot;到&quot;会用方法&quot;。</p><p><strong>《穷查理宝典》——长期价值的另一种表达</strong></p><p>《天道解读》讲&quot;长期价值思维消除焦虑&quot;，《穷查理宝典》讲&quot;每天进步一点点&quot;。芒格说：&quot;合理的预期是每年比去年聪明一点点。&quot;丁元英说：&quot;不现实的那一部分，是大众的思维不这么想。&quot;</p><h3 id="高阶批判" tabindex="-1">高阶批判 <a class="header-anchor" href="#高阶批判" aria-label="Permalink to &quot;高阶批判&quot;">​</a></h3><p><strong>2026年AI时代的修正</strong></p><p><strong>1. &quot;文化属性&quot;需要升级</strong></p><p>书中把文化属性分为强势文化和弱势文化，用&quot;等靠要&quot;描述弱势文化。在AI时代，这个划分需要修正：强势文化不是&quot;直接获取&quot;，而是&quot;会用工具&quot;。弱势文化不是&quot;等靠要&quot;，而是&quot;不知道AI能帮什么&quot;。</p><p>修正：文化属性的内核不变（思维模式），但表现形式变了。2026年的强势文化，是&quot;先问AI，再问人&quot;。</p><p><strong>2. &quot;神学宗教的社会功能&quot;面临挑战</strong></p><p>书中说&quot;神学也好，儒家文化也好，其本质都是让社会有序进行&quot;。在AI时代，这个&quot;有序&quot;正在被打破：信息垄断被打破、权威被质疑、职业边界被模糊。</p><p>修正：社会有序的根基从&quot;神学宗教&quot;转向&quot;算法伦理&quot;。我们要思考的不再是&quot;窄门在哪&quot;，而是&quot;AI的边界在哪&quot;。</p><p><strong>3. &quot;知行合一&quot;的AI化</strong></p><p>王阳明的知行合一，在AI时代有了新解：让AI成为你的&quot;行&quot;。你知道&quot;要写1000字&quot;，AI帮你写，这是另一种知行合一。</p><p>修正：知行合一的本质不变（意识与潜意识统一），但工具变了。2026年的&quot;知&quot;，包含&quot;知道AI能做什么&quot;；2026年的&quot;行&quot;，包含&quot;与AI协作&quot;。</p><hr><h2 id="📖-精彩摘录" tabindex="-1">📖 精彩摘录 <a class="header-anchor" href="#📖-精彩摘录" aria-label="Permalink to &quot;📖 精彩摘录&quot;">​</a></h2><blockquote><p>&quot;这世上原本就没有什么神话，所谓的神话不过是常人的思维所不理解的平常事。&quot;</p></blockquote><blockquote><p>&quot;天下熙熙皆为利来，天下攘攘皆为利往。&quot; ——司马迁《史记》</p></blockquote><blockquote><p>&quot;你不知道你，所以你是你。&quot; ——丁元英</p></blockquote><blockquote><p>&quot;圣人之道，吾性自足。&quot; ——王阳明龙场悟道</p></blockquote><blockquote><p>&quot;心即理，你能够看到自己是被&#39;理&#39;塑造，但是通过&#39;致良知&#39;重新塑造一个新的自己。&quot; ——本书</p></blockquote><blockquote><p>&quot;知道就一定会行动，如果没有行动，就一定不知道。&quot; ——本书对知行合一的解读</p></blockquote><blockquote><p>&quot;两点之间，线段最短。我不需要去预设自己，我就是。&quot; ——本书</p></blockquote><blockquote><p>&quot;你本具足，只是被&#39;理&#39;束缚而不自知。&quot;</p></blockquote>',123)])])}const d=t(a,[["render",r]]);export{g as __pageData,d as default};
